with feeders as (
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__PART_ID))) as HUB_PARTY_HK
        , HOSPITAL_DETAIL as FACILITY_NAME
        , cast(null as varchar) as AVAILABLE_INDICATOR
        , cast(null as varchar) as FACILITY_CATEGORY
        , cast(null as varchar) as CAPACITY
        , cast(null as varchar) as FACILITY_COUNT
        , cast(null as varchar) as ACCREDITATION_INDICATOR
        , cast(null as varchar) as CAPABILITY_REMARKS
        , cast(null as varchar) as ACCREDITATION_REFERENCE
        , 'BJAZ_HC_PART_EXTN' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hc_part_extn') }}
    where (nullif(trim(PART_ID),'')) is not null
    union all
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__HOSID))) as HUB_PARTY_HK
        , HOSP_SPECIALITY as FACILITY_NAME
        , DIAGNO_YN as AVAILABLE_INDICATOR
        , HOSP_SPEC_TYPE as FACILITY_CATEGORY
        , cast(null as varchar) as CAPACITY
        , cast(null as varchar) as FACILITY_COUNT
        , cast(null as varchar) as ACCREDITATION_INDICATOR
        , cast(null as varchar) as CAPABILITY_REMARKS
        , cast(null as varchar) as ACCREDITATION_REFERENCE
        , 'BJAZ_HM_HOSPITAL_MASTER' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_hospital_master') }}
    where (nullif(trim(HOSID),'')) is not null
    union all
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__HOSID))) as HUB_PARTY_HK
        , cast(null as varchar) as FACILITY_NAME
        , PHOTOTHERAPY as AVAILABLE_INDICATOR
        , cast(null as varchar) as FACILITY_CATEGORY
        , GENERAL_WARD_BEDS as CAPACITY
        , NO_OPRN_THEATRES as FACILITY_COUNT
        , cast(null as varchar) as ACCREDITATION_INDICATOR
        , cast(null as varchar) as CAPABILITY_REMARKS
        , cast(null as varchar) as ACCREDITATION_REFERENCE
        , 'BJAZ_HM_HOSPITAL_MASTER_EXTN' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_hospital_master_extn') }}
    where (nullif(trim(HOSID),'')) is not null
    union all
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__HOSID))) as HUB_PARTY_HK
        , cast(null as varchar) as FACILITY_NAME
        , INFECTNCTRL as AVAILABLE_INDICATOR
        , cast(null as varchar) as FACILITY_CATEGORY
        , RECOVERYROOMS as CAPACITY
        , NURSE_NO_ICU as FACILITY_COUNT
        , NABL as ACCREDITATION_INDICATOR
        , OPERATINGHRS as CAPABILITY_REMARKS
        , STAT_LVL_NQAS as ACCREDITATION_REFERENCE
        , 'BJAZ_HM_HOSP_MASTER_EXTN1' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_hosp_master_extn1') }}
    where (nullif(trim(HOSID),'')) is not null
),

resolved as (
    select
        HUB_PARTY_HK,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then FACILITY_NAME end) as FACILITY_NAME,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then AVAILABLE_INDICATOR end) as AVAILABLE_INDICATOR,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then FACILITY_CATEGORY end) as FACILITY_CATEGORY,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then CAPACITY end) as CAPACITY,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then FACILITY_COUNT end) as FACILITY_COUNT,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then ACCREDITATION_INDICATOR end) as ACCREDITATION_INDICATOR,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then CAPABILITY_REMARKS end) as CAPABILITY_REMARKS,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then ACCREDITATION_REFERENCE end) as ACCREDITATION_REFERENCE,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_PARTY_HK
),

hashed as (
    select
        *,
        case when FACILITY_NAME is not null or AVAILABLE_INDICATOR is not null or FACILITY_CATEGORY is not null or CAPACITY is not null or FACILITY_COUNT is not null or ACCREDITATION_INDICATOR is not null or CAPABILITY_REMARKS is not null or ACCREDITATION_REFERENCE is not null
                     then md5(upper(coalesce(cast(FACILITY_NAME as varchar), '') || '|' || coalesce(cast(AVAILABLE_INDICATOR as varchar), '') || '|' || coalesce(cast(FACILITY_CATEGORY as varchar), '') || '|' || coalesce(cast(CAPACITY as varchar), '') || '|' || coalesce(cast(FACILITY_COUNT as varchar), '') || '|' || coalesce(cast(ACCREDITATION_INDICATOR as varchar), '') || '|' || coalesce(cast(CAPABILITY_REMARKS as varchar), '') || '|' || coalesce(cast(ACCREDITATION_REFERENCE as varchar), '')))
                end as SAT_PARTY_PROVIDER_CAPABILITY_HASHDIFF
    from resolved
)

select * from hashed
where HUB_PARTY_HK is not null
  and SAT_PARTY_PROVIDER_CAPABILITY_HASHDIFF is not null
